INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 1,'Purpose & Mandate','The Group exists to build enduring African enterprise and steward capital, assets, technology and partnerships for lawful, sustainable and inclusive value creation.','Foundational',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=1);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 2,'Institutional Continuity','The institution shall be designed to outlive individual office holders. Corporate records, knowledge, assets, authority and succession arrangements shall be maintained so leadership transition does not destroy institutional capacity.','Foundational',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=2);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 3,'Separation of Powers','Ownership, Board oversight, executive management, assurance and stewardship functions shall have defined responsibilities and appropriate checks and balances.','Governance',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=3);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 4,'Reserved Matters','Material changes to ownership, constitutional purpose, major asset dispositions, extraordinary financing, related-party transactions and other matters designated by the Board or applicable law shall require prescribed approval before execution.','Governance',false,'As specified by Board policy and applicable law' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=4);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 5,'Indigenous & Community Rights','No Group entity shall knowingly structure a transaction to unlawfully extinguish legitimate indigenous ownership, customary interests, community rights or agreed benefit-sharing. Projects affecting communities require meaningful participation consistent with applicable law and recognised good practice.','Stewardship',true,'Enhanced approval and independent legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=5);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 6,'Land & Asset Stewardship','Land, natural resources, intellectual property, data and other strategic assets shall be acquired, developed and transferred through lawful title, documented authority, due diligence and transparent records.','Stewardship',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=6);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 7,'Subsidiaries & SPVs','Every subsidiary and special purpose vehicle shall have a defined purpose, ownership record, governance instrument, authority matrix, reporting obligations and ring-fenced asset boundary.','Structure',false,'Board approval and applicable law' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=7);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 8,'Fiduciary Integrity','Directors, officers and delegated decision makers shall act within authority, disclose conflicts, protect confidential information and place lawful institutional duties above undisclosed personal interests.','Ethics',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=8);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 9,'Succession & Continuity','Critical offices shall have documented succession, delegated continuity arrangements and institutional knowledge transfer. No individual office holder shall become a single point of failure for a material function.','Continuity',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=9);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 10,'Continental Expansion','The Group may establish regional offices, country entities, subsidiaries, partnerships and SPVs across Africa subject to local law, risk assessment and preservation of core constitutional principles.','Expansion',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=10);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 11,'Amendment & Interpretation','The constitutional framework shall be interpreted consistently with applicable corporate law and binding instruments. Amendments shall be documented, approved through the prescribed process and recorded in the institutional register.','Governance',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=11);
INSERT INTO constitutional_articles (article_no,title,text,category,protected,amendment_threshold) SELECT 12,'Dissolution & Stewardship','If an entity is wound up, assets shall be distributed only through lawful processes after settlement of obligations. Contractual community, investor, beneficiary or stewardship commitments shall be addressed before residual distributions.','Stewardship',true,'Special resolution and legal review' WHERE NOT EXISTS (SELECT 1 FROM constitutional_articles WHERE article_no=12);